import{_ as a,o as s,c as i,a2 as e}from"./chunks/framework.CvydjLy7.js";const k=JSON.parse('{"title":"三、SQL 初始化：schema.sql 与 data.sql","description":"","frontmatter":{"title":"三、SQL 初始化：schema.sql 与 data.sql"},"headers":[{"level":3,"title":"3.1 默认规则","slug":"_3-1-默认规则","link":"#_3-1-默认规则","children":[]},{"level":3,"title":"3.2 为什么必须加 defer-datasource-initialization","slug":"_3-2-为什么必须加-defer-datasource-initialization","link":"#_3-2-为什么必须加-defer-datasource-initialization","children":[]},{"level":3,"title":"3.3 spring.sql.init.* 全量属性","slug":"_3-3-spring-sql-init-全量属性","link":"#_3-3-spring-sql-init-全量属性","children":[]},{"level":3,"title":"3.4 版本化迁移：Flyway 与 Liquibase","slug":"_3-4-版本化迁移-flyway-与-liquibase","link":"#_3-4-版本化迁移-flyway-与-liquibase","children":[]},{"level":3,"title":"3.5 不要混用两套初始化机制","slug":"_3-5-不要混用两套初始化机制","link":"#_3-5-不要混用两套初始化机制","children":[]},{"level":3,"title":"3.6 Hibernate 的 import.sql","slug":"_3-6-hibernate-的-import-sql","link":"#_3-6-hibernate-的-import-sql","children":[]}],"relativePath":"ch06/03.md","filePath":"ch06/03.md","lastUpdated":1789497795000}'),d={name:"ch06/03.md"};function l(n,t,o,h,r,p){return s(),i("div",null,[...t[0]||(t[0]=[e(`<h1 id="三、sql-初始化-schema-sql-与-data-sql" tabindex="-1">三、SQL 初始化：schema.sql 与 data.sql <a class="header-anchor" href="#三、sql-初始化-schema-sql-与-data-sql" aria-label="Permalink to &quot;三、SQL 初始化：schema.sql 与 data.sql&quot;">​</a></h1><h3 id="_3-1-默认规则" tabindex="-1">3.1 默认规则 <a class="header-anchor" href="#_3-1-默认规则" aria-label="Permalink to &quot;3.1 默认规则&quot;">​</a></h3><p>Spring Boot 在类路径根目录下自动识别这几个文件：</p><table tabindex="0"><thead><tr><th>文件</th><th>默认位置</th><th>作用</th></tr></thead><tbody><tr><td><code>schema.sql</code></td><td><code>optional:classpath*:schema.sql</code></td><td>建表</td></tr><tr><td><code>data.sql</code></td><td><code>optional:classpath*:data.sql</code></td><td>灌数据</td></tr><tr><td><code>schema-\${platform}.sql</code></td><td>平台专属建表</td><td><code>\${platform}</code> 取自 <code>spring.sql.init.platform</code></td></tr><tr><td><code>data-\${platform}.sql</code></td><td>平台专属数据</td><td>同上</td></tr></tbody></table><p>三条规则必须记住：</p><ol><li><strong><code>optional:</code> 前缀意味着文件不存在也不报错</strong>。想让缺文件直接启动失败，把这个前缀去掉。</li><li><strong>默认只对嵌入式内存数据库执行</strong>（<code>spring.sql.init.mode</code> 默认 <code>embedded</code>）。连 MySQL 时不写脚本进去，这是刻意的保护。</li><li><strong>脚本默认在 JPA 的 <code>EntityManagerFactory</code> 创建之前执行</strong>——这一点直接引出下一个坑。</li></ol><h3 id="_3-2-为什么必须加-defer-datasource-initialization" tabindex="-1">3.2 为什么必须加 defer-datasource-initialization <a class="header-anchor" href="#_3-2-为什么必须加-defer-datasource-initialization" aria-label="Permalink to &quot;3.2 为什么必须加 defer-datasource-initialization&quot;">​</a></h3><p>JPA 项目里，如果让 Hibernate 负责建表（<code>ddl-auto</code>），而 <code>data.sql</code> 又先于建表执行，插入语句会报“表不存在”。本项目的解法：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">spring</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  jpa</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    hibernate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      ddl-auto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">create-drop</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 让 data.sql 在 Hibernate 建表之后执行</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    defer-datasource-initialization</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  sql</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    init</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">always</span></span></code></pre></div><p><code>defer-datasource-initialization: true</code> 的作用就是把 <code>DataSource</code> 初始化推迟到所有 <code>EntityManagerFactory</code> 创建完成之后。官方对这个开关的态度是<strong>有条件推荐</strong>：它本来是为了照顾“想用脚本补充 Hibernate 建出来的表”这种需求，属于混合方案。</p><h3 id="_3-3-spring-sql-init-全量属性" tabindex="-1">3.3 spring.sql.init.* 全量属性 <a class="header-anchor" href="#_3-3-spring-sql-init-全量属性" aria-label="Permalink to &quot;3.3 spring.sql.init.* 全量属性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>取值</th><th>说明</th></tr></thead><tbody><tr><td><code>spring.sql.init.mode</code></td><td><code>embedded</code>（默认）/ <code>always</code> / <code>never</code></td><td>何时执行脚本</td></tr><tr><td><code>spring.sql.init.schema-locations</code></td><td>路径列表</td><td>替换默认的 <code>schema.sql</code></td></tr><tr><td><code>spring.sql.init.data-locations</code></td><td>路径列表</td><td>替换默认的 <code>data.sql</code></td></tr><tr><td><code>spring.sql.init.platform</code></td><td>字符串</td><td>拼出 <code>schema-\${platform}.sql</code>，常填数据库厂商名</td></tr><tr><td><code>spring.sql.init.continue-on-error</code></td><td><code>true</code> / <code>false</code>（默认）</td><td>默认遇到错误即失败；设 <code>true</code> 可跳过出错语句</td></tr><tr><td><code>spring.sql.init.encoding</code></td><td>字符集</td><td>脚本编码</td></tr><tr><td><code>spring.sql.init.separator</code></td><td>分隔符</td><td>语句分隔符，默认 <code>;</code></td></tr></tbody></table><p>MyBatis-Plus 工程就得靠它显式指定脚本位置——因为 MyBatis-Plus 不会建表：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">spring</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  sql</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    init</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">always</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      schema-locations</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">classpath:schema.sql</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      data-locations</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">classpath:data.sql</span></span></code></pre></div><blockquote><p><strong>脚本注释只支持两种写法</strong></p><p>初始化脚本里只能用 <code>--</code> 行注释和 <code>/* */</code> 块注释。用 <code>#</code> 开头会当成 SQL 内容发出，直接报语法错误。</p></blockquote><h3 id="_3-4-版本化迁移-flyway-与-liquibase" tabindex="-1">3.4 版本化迁移：Flyway 与 Liquibase <a class="header-anchor" href="#_3-4-版本化迁移-flyway-与-liquibase" aria-label="Permalink to &quot;3.4 版本化迁移：Flyway 与 Liquibase&quot;">​</a></h3><p><code>schema.sql</code> 适合教学和演示，<strong>不适合生产</strong>：它没有版本概念，改一次表结构就得靠人肉记住哪些环境已经执行过。生产环境用迁移工具，Spring Boot 内置对接了两个（版本由官方 BOM 管理）：</p><table tabindex="0"><thead><tr><th>工具</th><th>BOM 版本</th><th>脚本位置</th><th>特点</th></tr></thead><tbody><tr><td>Flyway</td><td>12.4.0</td><td><code>classpath:db/migration</code></td><td>脚本名 <code>V1__init.sql</code>，SQL 为主，上手快</td></tr><tr><td>Liquibase</td><td>5.0.3</td><td><code>classpath:db/changelog</code></td><td>XML / YAML / SQL 均可，抽象的 changeset 概念，支持回滚</td></tr></tbody></table><p>两者都是“引依赖即生效”：把 <code>flyway-core</code> 放进 <code>pom.xml</code>，Spring Boot 在启动时自动执行迁移，并把执行记录写进 <code>flyway_schema_history</code> 表。配合上要注意一条：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">spring</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  jpa</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    hibernate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      ddl-auto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">validate</span></span></code></pre></div><p><strong>用迁移工具管表结构时，<code>ddl-auto</code> 必须改成 <code>validate</code></strong>（让 Hibernate 只校验实体与表是否一致，不动表结构），否则框架和迁移工具会互相打架。</p><h3 id="_3-5-不要混用两套初始化机制" tabindex="-1">3.5 不要混用两套初始化机制 <a class="header-anchor" href="#_3-5-不要混用两套初始化机制" aria-label="Permalink to &quot;3.5 不要混用两套初始化机制&quot;">​</a></h3><p>官方文档对这一条用了明确的措辞：如果使用 Flyway 或 Liquibase，就应该<strong>单独使用它们</strong>来创建和初始化 schema；把基础的 <code>schema.sql</code> / <code>data.sql</code> 与迁移工具并用是不推荐的，而且<strong>该支持将在未来版本中被移除</strong>。</p><p>所以正确的组合只有两种：</p><table tabindex="0"><thead><tr><th>场景</th><th>表结构</th><th>初始数据</th></tr></thead><tbody><tr><td>教学 / 演示</td><td><code>ddl-auto: create-drop</code></td><td><code>data.sql</code></td></tr><tr><td>生产</td><td>Flyway / Liquibase</td><td>Flyway / Liquibase</td></tr></tbody></table><h3 id="_3-6-hibernate-的-import-sql" tabindex="-1">3.6 Hibernate 的 import.sql <a class="header-anchor" href="#_3-6-hibernate-的-import-sql" aria-label="Permalink to &quot;3.6 Hibernate 的 import.sql&quot;">​</a></h3><p>还有个容易混淆的文件：类路径根目录下的 <code>import.sql</code>。它在 <code>ddl-auto</code> 为 <code>create</code> 或 <code>create-drop</code> 时由 <strong>Hibernate 自己</strong>执行——和 Spring 的 <code>data.sql</code> 是两套机制。本教程不用它，见到时知道它是 Hibernate 的特性即可。</p>`,27)])])}const g=a(d,[["render",l]]);export{k as __pageData,g as default};
